    tokens = []
    for match in token_re.finditer(expr):
        token = match.group()
        if token.isspace():
            continue
        if re.fullmatch(r"(?:\d+(?:\.\d*)?|\.\d+)", token) or token in "+-*/()":
            tokens.append(token)
        else:
            raise ValueError(f"Unknown character: {token!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while pos < len(tokens) and tokens[pos] in ("*", "/"):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0.0:
                    raise ZeroDivisionError("Division by zero")
                value /= rhs
        return value

    def parse_factor():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[pos]
        if token == "-":
            pos += 1
            return -parse_factor()
        if token == "(":
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("Unbalanced parentheses")
            pos += 1
            return value
